// Generated by ferreal-build: do not edit. Calls engine functions through reflection, for the
// bindings ferreal::engine! generates: each thunk fills a struct of the function's parameters
// (laid out by the C++ compiler) and calls ProcessEvent, as Unreal's own generated event
// thunks do. Before the first call, the struct is checked against the function's reflection:
// its size, and each parameter's name, offset, size and property class. A function that
// does not match, or does not exist in this build (editor-only functions in a game), is
// disabled: its calls log an error once and return zeros.

#ifndef FERREAL_ENGINE_0_1
#define FERREAL_ENGINE_0_1

#include "CoreMinimal.h"
#include "UObject/Class.h"
#include "UObject/UnrealType.h"
#include "UObject/UObjectGlobals.h"
#include "Ferreal/FerrealRuntime.h"

DEFINE_LOG_CATEGORY_STATIC(LogFerrealEngine, Log, All);

namespace Ferreal
{
	/** A parameter as the generated struct lays it out, and what reflection must say of it. */
	struct FEngineParam
	{
		template <typename P, typename M>
		FEngineParam(const P& Parms, const M& Member, const TCHAR* InName, const TCHAR* InProperty, const TCHAR* InStruct)
			: Name(InName)
			, Property(InProperty)
			, Struct(InStruct)
			, Offset(static_cast<int32>(reinterpret_cast<const uint8*>(&Member) - reinterpret_cast<const uint8*>(&Parms)))
			, Size(static_cast<int32>(sizeof(M)))
		{
		}

		const TCHAR* Name;
		/** The property classes accepted, separated by '|' ("IntProperty"). */
		const TCHAR* Property;
		/** For a struct: its name ("Vector"). */
		const TCHAR* Struct;
		int32 Offset;
		int32 Size;
	};

	/** The struct of a function's parameters: its sizeof and its parameters, in order (the return value last). */
	struct FEngineLayout
	{
		int32 Size;
		TArray<FEngineParam> Params;
	};

	/** A function of an engine class, called through reflection. One per thunk (a static). */
	class FEngineFunction
	{
	public:
		FEngineFunction(const TCHAR* InClassPath, const TCHAR* InName, bool bInStatic)
			: ClassPath(InClassPath)
			, Name(InName)
			, bStatic(bInStatic)
		{
		}

		/** Whether the function can be called: resolved and checked the first time (MakeLayout gives the struct). */
		template <typename F>
		bool Ready(F&& MakeLayout)
		{
			if (State == EState::Unresolved)
			{
				Resolve(MakeLayout());
			}
			return State == EState::Ready;
		}

		/** Calls it on Object (ignored for a static function) with the parameters at Parms. */
		void Call(UObject* Object, void* Parms)
		{
			UObject* Target = Object;
			UFunction* Callee = Function;
			if (bStatic)
			{
				Target = Class->GetDefaultObject();
			}
			else
			{
				if (!IsValid(Object) || !Object->IsA(Class))
				{
					UE_LOG(LogFerrealEngine, Error, TEXT("Ferreal: %s::%s called on %s, which is not a valid %s; skipped"),
						*Class->GetName(), Name, Object ? *Object->GetName() : TEXT("null"), *Class->GetName());
					return;
				}
				// The object's own version: a Blueprint's override of an event.
				if (UFunction* Override = Object->FindFunction(FunctionName); Override && Override->ParmsSize == Function->ParmsSize)
				{
					Callee = Override;
				}
			}
			Target->ProcessEvent(Callee, Parms);
		}

	private:
		enum class EState : uint8
		{
			Unresolved,
			Ready,
			Failed,
		};

		void Fail(const FString& Why)
		{
			State = EState::Failed;
			UE_LOG(LogFerrealEngine, Error, TEXT("Ferreal: %s.%s cannot be called from Rust: %s. Rebuild the Rust after updating the engine or the classes (the bindings may be stale)."),
				ClassPath, Name, *Why);
		}

		static bool PropertyMatches(const FProperty* Prop, const FEngineParam& P)
		{
			return PropertyMatches(Prop, FString(P.Property), P.Struct);
		}

		/** Property: the accepted property classes, `|` between; `ArrayProperty/<the element's>` for an array. */
		static bool PropertyMatches(const FProperty* Prop, const FString& Property, const TCHAR* Struct)
		{
			FString Outer = Property;
			FString Inner;
			if (Property.Split(TEXT("/"), &Outer, &Inner))
			{
				const FArrayProperty* Array = CastField<FArrayProperty>(Prop);
				return Outer == TEXT("ArrayProperty") && Array && Array->Inner && PropertyMatches(Array->Inner, Inner, Struct);
			}
			TArray<FString> Accepted;
			Outer.ParseIntoArray(Accepted, TEXT("|"));
			if (!Accepted.Contains(Prop->GetClass()->GetName()))
			{
				return false;
			}
			if (Struct)
			{
				const FStructProperty* S = CastField<FStructProperty>(Prop);
				return S && S->Struct && S->Struct->GetName() == Struct;
			}
			return true;
		}

		void Resolve(const FEngineLayout& Layout)
		{
			Class = FindObject<UClass>(nullptr, ClassPath);
			if (!Class)
			{
				Fail(TEXT("the class is not loaded (is its module?)"));
				return;
			}
			FunctionName = FName(Name);
			Function = Class->FindFunctionByName(FunctionName);
			if (!Function)
			{
				Fail(TEXT("the function does not exist in this build (an editor-only function in a game?)"));
				return;
			}
			// ParmsSize ends at the last parameter (unpadded); the struct holds at least that.
			int32 End = 0;
			for (const FEngineParam& P : Layout.Params)
			{
				End = FMath::Max(End, P.Offset + P.Size);
			}
			if (Function->ParmsSize != End || Layout.Size < End)
			{
				Fail(FString::Printf(TEXT("its parameters end at byte %d, the generated struct's at %d"), static_cast<int32>(Function->ParmsSize), End));
				return;
			}
			int32 Index = 0;
			for (TFieldIterator<FProperty> It(Function); It && It->HasAnyPropertyFlags(CPF_Parm); ++It, ++Index)
			{
				if (Index >= Layout.Params.Num())
				{
					Fail(FString::Printf(TEXT("it has more than the %d parameters generated"), Layout.Params.Num()));
					return;
				}
				const FEngineParam& P = Layout.Params[Index];
				const FProperty* Prop = *It;
				if (Prop->GetName() != P.Name || Prop->GetOffset_ForUFunction() != P.Offset || Prop->GetSize() != P.Size || !PropertyMatches(Prop, P))
				{
					Fail(FString::Printf(TEXT("parameter %d is %s (%s, %d bytes at %d), the generated struct has %s (%s, %d bytes at %d)"),
						Index, *Prop->GetName(), *Prop->GetClass()->GetName(), Prop->GetSize(), Prop->GetOffset_ForUFunction(),
						P.Name, P.Property, P.Size, P.Offset));
					return;
				}
			}
			if (Index != Layout.Params.Num())
			{
				Fail(FString::Printf(TEXT("it has %d parameters, the generated struct %d"), Index, Layout.Params.Num()));
				return;
			}
			State = EState::Ready;
		}

		const TCHAR* ClassPath;
		const TCHAR* Name;
		bool bStatic;
		EState State = EState::Unresolved;
		UClass* Class = nullptr;
		UFunction* Function = nullptr;
		FName FunctionName;
	};
}

#endif // FERREAL_ENGINE_0_1
